class Solution:
    def largestInteger(self, num: int) -> int:
        s = str(num)
        ev = sorted((int(c) for c in s if int(c) % 2 == 0), reverse=True)
        od = sorted((int(c) for c in s if int(c) % 2), reverse=True)
        ei = oi = 0
        res = []
        for c in s:
            if int(c) % 2 == 0:
                res.append(ev[ei]); ei += 1
            else:
                res.append(od[oi]); oi += 1
        return int(''.join(map(str, res)))

