class Solution {
public:
    int largestInteger(int num) {
        string s = to_string(num);
        vector<int> e, o;
        for (char c : s) ((c - '0') % 2 ? o : e).push_back(c - '0');
        sort(e.rbegin(), e.rend());
        sort(o.rbegin(), o.rend());
        int ie = 0, io = 0;
        string r;
        for (char c : s) {
            if ((c - '0') % 2) r += '0' + o[io++];
            else r += '0' + e[ie++];
        }
        return stoi(r);
    }
};

