class Solution {
    public int largestInteger(int num) {
        char[] s = String.valueOf(num).toCharArray();
        List<Integer> e = new ArrayList<>(), o = new ArrayList<>();
        for (char c : s) ((c - '0') % 2 ? o : e).add(c - '0');
        Collections.sort(e, Collections.reverseOrder());
        Collections.sort(o, Collections.reverseOrder());
        int ie = 0, io = 0;
        StringBuilder r = new StringBuilder();
        for (char c : s) {
            if ((c - '0') % 2 == 1) r.append(o.get(io++));
            else r.append(e.get(ie++));
        }
        return Integer.parseInt(r.toString());
    }
}

