var largestInteger = function(num) {
    const s = String(num).split('').map(Number);
    const ev = s.filter(x => x % 2 === 0).sort((a, b) => b - a);
    const od = s.filter(x => x % 2 === 1).sort((a, b) => b - a);
    let ei = 0, oi = 0;
    return parseInt(s.map(x => x % 2 === 0 ? ev[ei++] : od[oi++]).join(''));
};
